const LEGACY_STORAGE_PREFIX = "tinyTitans.reptileRoom.layout.v6";
const DEFAULT_ROOM = { width: 360, depth: 300, height: 240, storageCapacity: 12 };
const DEFAULT_VIV = { width: 60, depth: 40, height: 30 };
const SNAP_CM = 5;
const WALL_SNAP_CM = 12;

type LayoutPreset = "freeform" | "rack" | "wall" | "grid";
type Drawer = "asset" | "object" | "storage" | null;
type AssetDraft = { label: string; width: string; depth: string; height: string; storageLocation: string; storageNote: string; notes: string; maintenanceNote: string };
