type RoomDraft = { width: string; depth: string; height: string; storageCapacity: string };

const TEMPLATE_NAMES: Record<ReptileRoomTemplate, string> = { blank: "Blank room", hatchling: "Hatchling room", breeding: "Breeding room", medical: "Medical / quarantine", brumation: "Brumation room", bioactive: "Bioactive room", custom: "Custom room" };
const STATUS_LABELS: Record<VivariumLifecycleStatus, string> = { active: "Active", stored: "Stored", empty: "Empty", reserved: "Reserved", retired: "Retired", quarantine: "Quarantine", breeding: "Breeding setup" };
const CONDITION_LABELS: Record<VivariumCondition, string> = { excellent: "Excellent", good: "Good", fair: "Fair", "needs-repair": "Needs repair", retired: "Retired" };
const FURNITURE_LABELS: Record<ReptileFurnitureKind, string> = { rack: "Rack", shelving: "Shelving", workbench: "Workbench", "storage-cabinet": "Storage cabinet", "equipment-station": "Heat / equipment station", "quarantine-area": "Quarantine area", door: "Door", window: "Window", vent: "Vent" };
const WALL_LABELS: Record<ReptileWall, string> = { north: "North wall", east: "East wall", south: "South wall", west: "West wall" };
const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const num = (value: string, fallback = 0) => { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : fallback; };
const makeId = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
function legacyKey(uid: string) { return `${LEGACY_STORAGE_PREFIX}:${uid}`; }
function readLegacyLayout(uid: string): ReptileRoomSlot[] { try { const raw = localStorage.getItem(legacyKey(uid)); if (!raw) return []; const parsed = JSON.parse(raw) as unknown; if (!Array.isArray(parsed)) return []; return parsed.filter((item): item is ReptileRoomSlot => Boolean(item) && typeof item === "object" && typeof (item as ReptileRoomSlot).id === "string" && typeof (item as ReptileRoomSlot).x === "number" && typeof (item as ReptileRoomSlot).y === "number").map((slot) => ({ ...slot, snakeId: typeof slot.snakeId === "string" ? slot.snakeId : null, label: typeof slot.label === "string" ? slot.label : "Vivarium", w: Number(slot.w) || DEFAULT_VIV.width, h: Number(slot.h) || DEFAULT_VIV.depth })); } catch { return []; } }
function toDisplay(cm: number, unit: ReptileRoomUnit) { return unit === "imperial" ? cm / 2.54 : cm; }
function fromDisplay(value: number, unit: ReptileRoomUnit) { return unit === "imperial" ? value * 2.54 : value; }
function formatDim(cm: number, unit: ReptileRoomUnit) { return `${toDisplay(cm, unit).toFixed(cm >= 100 ? 0 : 1)} ${unit === "imperial" ? "in" : "cm"}`; }
function defaultSlot(snake: Snake | null, index: number): ReptileRoomSlot { const width = Number(snake?.enclosure?.length) || DEFAULT_VIV.width; const depth = Number(snake?.enclosure?.width) || DEFAULT_VIV.depth; const height = Number(snake?.enclosure?.height) || DEFAULT_VIV.height; return { id: makeId("viv"), snakeId: snake?.id ?? null, label: snake ? `${snake.name}'s Vivarium` : `Vivarium ${String(index + 1).padStart(2, "0")}`, x: 10 + (index % 4) * Math.min(width + 12, 82), y: 12 + Math.floor(index / 4) * Math.min(depth + 14, 70), w: width, h: depth, depth, height, lifecycleStatus: snake ? "active" : "empty", condition: "good", availability: snake ? "occupied" : "available", storageLocation: "", storageNote: "", notes: "", maintenanceNote: "" }; }
function normalizeSlot(slot: ReptileRoomSlot, snakeById: Map<string, Snake>): ReptileRoomSlot { const snake = slot.snakeId ? snakeById.get(slot.snakeId) : null; const width = Number(slot.w) || Number(snake?.enclosure?.length) || DEFAULT_VIV.width; const depth = Number(slot.h) || Number(snake?.enclosure?.width) || DEFAULT_VIV.depth; return { ...slot, w: width, h: depth, depth: Number(slot.depth) || depth, height: Number(slot.height) || Number(snake?.enclosure?.height) || DEFAULT_VIV.height, lifecycleStatus: slot.lifecycleStatus ?? (snake ? "active" : "empty"), condition: slot.condition ?? "good", availability: slot.availability ?? (snake ? "occupied" : "available"), storageLocation: slot.storageLocation ?? "", storageNote: slot.storageNote ?? "", notes: slot.notes ?? "", maintenanceNote: slot.maintenanceNote ?? "" }; }
