  useEffect(() => { if (selectedObject) setObjectDraft(objectDraftFor(selectedObject, roomUnit)); else setObjectDraft(null); }, [selectedObjectId, selectedObject?.width, selectedObject?.depth, selectedObject?.height, selectedObject?.rotation, selectedObject?.openingType, roomUnit]);
  const updateActiveRoom = useCallback((updater: (room: ReptileRoomWorkspace) => ReptileRoomWorkspace, successMessage?: string) => { const current = roomsRef.current; const room = current.find((item) => item.id === activeRoomId); if (!room) return; void persistRooms(current.map((item) => item.id === room.id ? updater(room) : item), successMessage); }, [activeRoomId, persistRooms]);

  function addVivarium() { if (!activeRoom) return; const slot = defaultSlot(null, slots.length + storedSlots.length); slot.x = clamp(Math.round((10 + (slots.length % 4) * 72) / SNAP_CM) * SNAP_CM, 0, Math.max(0, roomWidth - slot.w)); slot.y = clamp(Math.round((10 + Math.floor(slots.length / 4) * 58) / SNAP_CM) * SNAP_CM, 0, Math.max(0, roomDepth - slot.h)); updateActiveRoom((room) => ({ ...room, slots: [...room.slots, slot] })); setSelectedSlotId(slot.id); setSelectedObjectId(null); setDrawer("asset"); }
  function duplicateVivarium(slot: ReptileRoomSlot) { const copy = { ...slot, id: makeId("viv"), snakeId: null, label: `${slot.label} copy`, x: clamp(slot.x + slot.w + SNAP_CM, 0, Math.max(0, roomWidth - slot.w)), lifecycleStatus: "empty" as VivariumLifecycleStatus, availability: "available" as VivariumAvailability }; updateActiveRoom((room) => ({ ...room, slots: [...room.slots, copy] })); setSelectedSlotId(copy.id); setDrawer("asset"); }
  function storeVivarium(slotId: string) { const room = roomsRef.current.find((item) => item.id === activeRoomId); const slot = room?.slots.find((item) => item.id === slotId); if (!room || !slot) return; const stored = { ...slot, lifecycleStatus: "stored" as VivariumLifecycleStatus, storageLocation: slot.storageLocation || "Vivarium Storage", availability: slot.snakeId ? "occupied" as VivariumAvailability : "available" as VivariumAvailability }; void persistRooms(roomsRef.current.map((item) => item.id === room.id ? { ...item, slots: item.slots.filter((s) => s.id !== slotId), storedSlots: [...item.storedSlots, stored] } : item), "Vivarium moved to storage. Snake history remains untouched."); setSelectedSlotId(null); setDrawer(null); }
  function retireStored(slotId: string, roomId: string) { void persistRooms(roomsRef.current.map((room) => room.id === roomId ? { ...room, storedSlots: room.storedSlots.map((slot) => slot.id === slotId ? { ...slot, lifecycleStatus: "retired" as VivariumLifecycleStatus, condition: "retired" as VivariumCondition } : slot) } : room), "Vivarium retired. It remains in asset history."); }
  function restoreToRoom(slotId: string, sourceRoomId: string, destinationRoomId: string) { const source = roomsRef.current.find((room) => room.id === sourceRoomId); const destination = roomsRef.current.find((room) => room.id === destinationRoomId); const stored = source?.storedSlots.find((slot) => slot.id === slotId); if (!source || !destination || !stored) return; const restored = { ...stored, lifecycleStatus: stored.snakeId ? "active" as VivariumLifecycleStatus : "empty" as VivariumLifecycleStatus, x: 0, y: 0, storageLocation: "", storageNote: "" }; const next = roomsRef.current.map((room) => room.id === sourceRoomId ? { ...room, storedSlots: room.storedSlots.filter((slot) => slot.id !== slotId) } : room.id === destinationRoomId ? { ...room, slots: [...room.slots, { ...restored, x: clamp(0, 0, Math.max(0, (room.width ?? DEFAULT_ROOM.width) - restored.w)), y: clamp(0, 0, Math.max(0, (room.depth ?? DEFAULT_ROOM.depth) - restored.h)) }] } : room); void persistRooms(next, `Vivarium restored to ${destination.name}.`); setActiveRoomId(destinationRoomId); setSelectedSlotId(restored.id); setDrawer("asset"); }
  function duplicateRoom() { if (!activeRoom) return; const now = new Date().toISOString(); const copy: ReptileRoomWorkspace = { ...activeRoom, id: makeId("room"), name: `${activeRoom.name} — Planning Copy`, slots: activeRoom.slots.map((slot) => ({ ...slot, id: makeId("viv"), snakeId: null, lifecycleStatus: "empty", availability: "available", label: `${slot.label} plan` })), storedSlots: activeRoom.storedSlots.map((slot) => ({ ...slot, id: makeId("viv") })), objects: activeRoom.objects?.map((object) => ({ ...object, id: makeId("obj") })) ?? [], createdAt: now, updatedAt: now }; void persistRooms([...roomsRef.current, copy], "Planning copy created. No snakes were moved."); setActiveRoomId(copy.id); setSelectedSlotId(null); setDrawer(null); }
  function removeRoom() { if (!activeRoom || roomsRef.current.length <= 1 || !user) return; const remaining = roomsRef.current.filter((room) => room.id !== activeRoom.id); void deleteReptileRoom(user.uid, activeRoom.id).then(() => { replaceRooms(remaining); setActiveRoomId(remaining[0].id); setSelectedSlotId(null); setDrawer(null); setMessage(`${activeRoom.name} removed.`); }).catch((error) => setMessage(error instanceof Error ? error.message : "Unable to remove the room.")); }
  function commitRoomField(key: keyof RoomDraft) { if (!activeRoom) return; const raw = roomDraft[key]; if (raw.trim() === "") { setRoomDraft(roomDraftFor(activeRoom, roomUnit)); return; } const value = key === "storageCapacity" ? Math.max(0, Math.round(num(raw))) : Math.max(50, fromDisplay(num(raw), roomUnit)); if (!Number.isFinite(value)) return; updateActiveRoom((room) => ({ ...room, [key]: value })); }
  function changeRoomUnit(unit: ReptileRoomUnit) { if (activeRoom) updateActiveRoom((room) => ({ ...room, unit })); }
  function saveRoomName() { const name = roomNameDraft.trim(); if (name) updateActiveRoom((room) => ({ ...room, name }), "Room name saved."); }
  function assignSnake(slotId: string, snakeId: string) { const target = snakeId || null; const snake = target ? snakeById.get(target) : null; const next = roomsRef.current.map((room) => ({ ...room, slots: room.slots.map((slot) => slot.id === slotId ? { ...slot, snakeId: target, lifecycleStatus: target ? "active" as VivariumLifecycleStatus : "empty" as VivariumLifecycleStatus, availability: target ? "occupied" as VivariumAvailability : "available" as VivariumAvailability, label: target ? `${snake?.name ?? "Snake"}'s Vivarium` : slot.label } : target && slot.snakeId === target ? { ...slot, snakeId: null, lifecycleStatus: "empty" as VivariumLifecycleStatus, availability: "available" as VivariumAvailability } : slot) })); void persistRooms(next, snake ? `${snake.name} assigned to this vivarium.` : "Vivarium unassigned."); }
