  const objectDefaults: Record<ReptileFurnitureKind, [number, number, number]> = { rack: [120, 50, 200], shelving: [100, 40, 180], workbench: [140, 70, 90], "storage-cabinet": [100, 50, 180], "equipment-station": [80, 50, 100], "quarantine-area": [120, 80, 100], door: [90, 12, 210], window: [120, 10, 100], vent: [30, 10, 10] };
