  function snapItem(x: number, y: number, w: number, h: number, object?: ReptileRoomObject) { let nx = Math.round(x / SNAP_CM) * SNAP_CM; let ny = Math.round(y / SNAP_CM) * SNAP_CM; const roomW = activeRoom?.width ?? DEFAULT_ROOM.width; const roomD = activeRoom?.depth ?? DEFAULT_ROOM.depth; if (object && ["door", "window", "vent"].includes(object.kind)) { const distances = [{ wall: "north" as ReptileWall, d: Math.abs(ny) }, { wall: "south" as ReptileWall, d: Math.abs(roomD - (ny + h)) }, { wall: "west" as ReptileWall, d: Math.abs(nx) }, { wall: "east" as ReptileWall, d: Math.abs(roomW - (nx + w)) }]; const nearest = distances.sort((a, b) => a.d - b.d)[0]; if (nearest.d <= WALL_SNAP_CM) { const snapped = snapWall({ ...object, x: nx, y: ny, width: w, depth: h }, nearest.wall); return { x: snapped.x, y: snapped.y, wall: nearest.wall, rotation: snapped.rotation }; } } const edgeX = Math.min(Math.abs(nx), Math.abs(roomW - (nx + w))); const edgeY = Math.min(Math.abs(ny), Math.abs(roomD - (ny + h))); if (edgeX <= WALL_SNAP_CM) nx = Math.abs(nx) < Math.abs(roomW - (nx + w)) ? 0 : Math.max(0, roomW - w); if (edgeY <= WALL_SNAP_CM) ny = Math.abs(ny) < Math.abs(roomD - (ny + h)) ? 0 : Math.max(0, roomD - h); return { x: clamp(nx, 0, Math.max(0, roomW - w)), y: clamp(ny, 0, Math.max(0, roomD - h)), wall: null, rotation: object?.rotation ?? 0 }; }
  function addObject(kind: ReptileFurnitureKind) { if (!activeRoom) return; const [width, depth, height] = objectDefaults[kind]; let object: ReptileRoomObject = { id: makeId("obj"), kind, label: FURNITURE_LABELS[kind], x: 10, y: 10, width, depth, height, rotation: 0, wall: kind === "door" || kind === "window" || kind === "vent" ? "north" : null, openingType: kind === "door" ? "swing" : undefined, notes: "" }; if (object.wall) object = snapWall(object, object.wall); updateActiveRoom((room) => ({ ...room, objects: [...(room.objects ?? []), object] })); setSelectedObjectId(object.id); setSelectedSlotId(null); setDrawer("object"); }
  function updateObject(objectId: string, patch: Partial<ReptileRoomObject>) { const current = roomsRef.current; const room = current.find((item) => item.id === activeRoomId); if (!room) return; void persistRooms(current.map((item) => item.id === room.id ? { ...room, objects: (room.objects ?? []).map((object) => object.id === objectId ? { ...object, ...patch } : object) } : item)); }
  function commitObjectField(key: keyof ObjectDraft) { if (!selectedObject || !objectDraft) return; if (key === "openingType") { updateObject(selectedObject.id, { openingType: objectDraft.openingType }); return; } if (["width", "depth", "height"].includes(key)) { const raw = objectDraft[key].trim(); if (!raw) { setObjectDraft(objectDraftFor(selectedObject, roomUnit)); return; } const value = Math.max(1, fromDisplay(num(raw), roomUnit)); if (key === "width") updateObject(selectedObject.id, { width: value }); if (key === "depth") updateObject(selectedObject.id, { depth: value }); if (key === "height") updateObject(selectedObject.id, { height: value }); return; } if (key === "rotation") updateObject(selectedObject.id, { rotation: num(objectDraft.rotation) }); else updateObject(selectedObject.id, { [key]: objectDraft[key] }); }
  function removeObject(objectId: string) { void persistRooms(roomsRef.current.map((room) => room.id === activeRoomId ? { ...room, objects: (room.objects ?? []).filter((object) => object.id !== objectId) } : room), "Room object removed."); setSelectedObjectId(null); setDrawer(null); }
  function moveItem(id: string, clientX: number, clientY: number, rect: DOMRect, isObject: boolean) { const room = roomsRef.current.find((item) => item.id === activeRoomId); if (!room || !rect.width || !rect.height) return; const roomW = room.width ?? DEFAULT_ROOM.width; const roomD = room.depth ?? DEFAULT_ROOM.depth; if (isObject) { const object = room.objects?.find((item) => item.id === id); if (!object) return; const rawX = ((clientX - rect.left) / rect.width) * roomW - object.width / 2; const rawY = ((clientY - rect.top) / rect.height) * roomD - object.depth / 2; const snapped = snapItem(rawX, rawY, object.width, object.depth, object); replaceRooms(roomsRef.current.map((item) => item.id === room.id ? { ...item, objects: (item.objects ?? []).map((entry) => entry.id === id ? { ...entry, x: snapped.x, y: snapped.y, wall: snapped.wall, rotation: snapped.rotation } : entry) } : item)); } else { const slot = room.slots.find((item) => item.id === id); if (!slot) return; const rawX = ((clientX - rect.left) / rect.width) * roomW - slot.w / 2; const rawY = ((clientY - rect.top) / rect.height) * roomD - slot.h / 2; const snapped = snapItem(rawX, rawY, slot.w, slot.h); replaceRooms(roomsRef.current.map((item) => item.id === room.id ? { ...item, slots: item.slots.map((entry) => entry.id === id ? { ...entry, x: snapped.x, y: snapped.y } : entry) } : item)); } }
  function pointerDrag(event: ReactPointerEvent<HTMLElement>, id: string, isObject: boolean) { if (!editMode) return; const canvas = event.currentTarget.closest(".reptile-room-floor") as HTMLElement | null; if (!canvas) return; event.preventDefault(); event.stopPropagation(); setDragging(id); const rect = canvas.getBoundingClientRect(); const onMove = (move: PointerEvent) => moveItem(id, move.clientX, move.clientY, rect, isObject); const onUp = () => { document.removeEventListener("pointermove", onMove); document.removeEventListener("pointerup", onUp); setDragging(null); void persistRooms(roomsRef.current); }; document.addEventListener("pointermove", onMove); document.addEventListener("pointerup", onUp); }
  function applyPreset(preset: LayoutPreset) { if (!activeRoom) return; const roomW = activeRoom.width ?? DEFAULT_ROOM.width; const roomD = activeRoom.depth ?? DEFAULT_ROOM.depth; const nextSlots = slots.map((slot, index) => { if (preset === "rack") return { ...slot, x: clamp(10 + (index % 4) * Math.min(slot.w + 8, 90), 0, Math.max(0, roomW - slot.w)), y: clamp(10 + Math.floor(index / 4) * Math.min(slot.h + 10, 65), 0, Math.max(0, roomD - slot.h)) }; if (preset === "wall") return { ...slot, x: clamp(8 + (index % 3) * Math.min(slot.w + 10, 120), 0, Math.max(0, roomW - slot.w)), y: 8 }; if (preset === "grid") return { ...slot, x: clamp(8 + (index % 3) * Math.min(slot.w + 14, 115), 0, Math.max(0, roomW - slot.w)), y: clamp(12 + Math.floor(index / 3) * Math.min(slot.h + 14, 80), 0, Math.max(0, roomD - slot.h)) }; return { ...slot, x: clamp(Math.round(slot.x / SNAP_CM) * SNAP_CM, 0, Math.max(0, roomW - slot.w)), y: clamp(Math.round(slot.y / SNAP_CM) * SNAP_CM, 0, Math.max(0, roomD - slot.h)) }; }); void persistRooms(roomsRef.current.map((room) => room.id === activeRoom.id ? { ...room, slots: nextSlots } : room)); }
  async function recordReplacement(item: EquipmentMaintenanceItem) { if (!user || !selectedSnake?.enclosure) return; setSavingSnakeId(selectedSnake.id); const today = new Date().toISOString().slice(0, 10); const equipmentMaintenance = (selectedSnake.enclosure.equipmentMaintenance ?? []).map((entry) => entry.id === item.id ? { ...entry, lastReplacedDate: today } : entry); try { const updated = await updateUserSnake(user.uid, { ...selectedSnake, enclosure: { ...selectedSnake.enclosure, equipmentMaintenance } }); setSnakes((current) => current.map((snake) => snake.id === updated.id ? updated : snake)); setMessage(`${item.name} replacement recorded.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Unable to save the replacement record."); } finally { setSavingSnakeId(null); } }
  if (loading || profileLoading || loadingRoom) return <div className="page-container"><BackHomeButton /><h1>🏠 My Reptile Room</h1><div className="tracker-card"><h3>Building your room…</h3><p>Loading rooms, vivarium assets and furniture.</p></div></div>;
