    <section className="reptile-room-floor-shell"><div className="floor-ruler floor-ruler-x"><span>0</span><span>{formatDim(roomWidth / 2, roomUnit)}</span><span>{formatDim(roomWidth, roomUnit)}</span></div><div className="reptile-room-floor" style={{ aspectRatio: `${roomWidth} / ${roomDepth}` }} aria-label={`${activeRoom?.name ?? "Reptile room"} scaled floor plan`}><div className="floor-wall-label">{activeRoom?.name.toUpperCase()} • {formatDim(roomWidth, roomUnit)} × {formatDim(roomDepth, roomUnit)}</div>{objects.map((object) => <button type="button" key={object.id} className={`room-object room-object-${object.kind} ${selectedObjectId === object.id ? "is-selected" : ""} ${dragging === object.id ? "is-dragging" : ""}`} style={{ left: `${object.x / roomWidth * 100}%`, top: `${object.y / roomDepth * 100}%`, width: `${object.width / roomWidth * 100}%`, height: `${object.depth / roomDepth * 100}%`, transform: `rotate(${object.rotation}deg)` }} onPointerDown={(event) => pointerDrag(event, object.id, true)} onClick={() => { setSelectedObjectId(object.id); setSelectedSlotId(null); setDrawer("object"); }}><strong>{FURNITURE_LABELS[object.kind]}</strong><small>{object.label}{object.wall ? ` • ${WALL_LABELS[object.wall]}` : ""}{object.kind === "door" ? ` • ${object.openingType === "sliding" ? "Sliding" : "Swing"}` : ""}</small></button>)}{slots.map((slot) => { const snake = slot.snakeId ? snakeById.get(slot.snakeId) : null; return <button type="button" key={slot.id} className={`room-vivarium ${selectedSlotId === slot.id ? "is-selected" : ""} ${dragging === slot.id ? "is-dragging" : ""} status-${slot.lifecycleStatus ?? "empty"}`} style={{ left: `${slot.x / roomWidth * 100}%`, top: `${slot.y / roomDepth * 100}%`, width: `${slot.w / roomWidth * 100}%`, height: `${slot.h / roomDepth * 100}%` }} onPointerDown={(event) => pointerDrag(event, slot.id, false)} onClick={() => { setSelectedSlotId(slot.id); setSelectedObjectId(null); setDrawer("asset"); }} aria-label={`${slot.label}${snake ? `, ${snake.name}` : ", empty"}`}><span className="room-vivarium-top"><strong>{snake?.name || slot.label}</strong><em>{STATUS_LABELS[slot.lifecycleStatus ?? "empty"]}</em></span><span className="room-vivarium-dims">{formatDim(slot.w, roomUnit)} × {formatDim(slot.h, roomUnit)} × {formatDim(slot.height ?? DEFAULT_VIV.height, roomUnit)}</span><span className="room-vivarium-snake">{snake ? `🐍 ${snake.name}` : "EMPTY / AVAILABLE"}</span></button>})}{!slots.length && <div className="reptile-room-empty"><strong>Your physical room is ready.</strong><p>Add vivariums and furniture, then drag them into position. Magnet snapping is enabled.</p><button type="button" className="add-snake-button" onClick={addVivarium}>➕ Add First Vivarium</button></div>}</div></section>
