    {drawer === "storage" && <aside className="room-drawer room-storage-drawer"><div className="drawer-head"><div><p className="reptile-room-eyebrow">📦 ASSET STORAGE</p><h2>Vivarium Storage</h2><p>Stored assets can be restored into any room without changing the snake's history.</p></div><button type="button" onClick={() => setDrawer(null)}>✕</button></div><div className="storage-capacity"><strong>{allStored.length}/{storageCapacity}</strong><span>stored across {rooms.length} room workspace{rooms.length === 1 ? "" : "s"}</span></div>{allStored.length ? <div className="drawer-list">{allStored.map(({ slot, room }) => { const snake = slot.snakeId ? snakeById.get(slot.snakeId) : null; return <article key={`${room.id}-${slot.id}`} className="storage-asset"><div><strong>{snake?.name || slot.label}</strong><span>{room.name} • {STATUS_LABELS[slot.lifecycleStatus ?? "stored"]}</span><small>{formatDim(slot.w, roomUnit)} × {formatDim(slot.h, roomUnit)} × {formatDim(slot.height ?? DEFAULT_VIV.height, roomUnit)} • {CONDITION_LABELS[slot.condition ?? "good"]}</small>{slot.storageLocation && <small>📍 {slot.storageLocation}</small>}{slot.storageNote && <small>📝 {slot.storageNote}</small>}</div><div className="storage-actions"><select aria-label={`Restore ${slot.label}`} defaultValue="" onChange={(event) => restoreToRoom(slot.id, room.id, event.target.value)}><option value="" disabled>Restore to…</option>{rooms.map((destination) => <option key={destination.id} value={destination.id}>{destination.name}</option>)}</select><button type="button" onClick={() => retireStored(slot.id, room.id)}>Retire</button></div></article>; })}</div> : <div className="equipment-empty"><strong>Storage is empty.</strong><p>Store a vivarium from its edit drawer.</p></div>}</aside>}
